class Base {
public:
    // Generates a VTable for Base
    virtual void process() {} 
    // Necessary for derived cleanup via Base ptr
    virtual ~Base() {}     
};

class Derived : public Base {
public:
    // Overrides VTable entry 0
    void process() override {} 
};

// Polymorphism via base pointer
Base* ptr = new Derived();

// Runtime dispatch via VPTR lookup
// (VPTR -> VTable[0] -> Derived::process)
ptr->process(); 

delete ptr; // Calls Derived::~Derived then Base::~Base
